import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Validate report type against allowed values
        if (reportType == null || !reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date range validation
        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // Department parameter is used directly in query construction
        // for dynamic table partitioning lookup
        String partitionTable = "reports_" + department;

        String query = "SELECT r.id, r.created_at, r.payload, r.status " +
                       "FROM " + partitionTable + " r " +
                       "WHERE r.created_at BETWEEN '" + startDate + "' AND '" + endDate + "' " +
                       "AND r.report_type = '" + reportType + "' " +
                       "ORDER BY r.created_at DESC LIMIT 500";

        log.info("Executing report query for dept=" + department + " type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("{\"id\":%d,\"created_at\":\"%s\",\"status\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("created_at"),
                    rs.getString("status"));
            }
            out.print("\n]");

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates async report jobs - delegates to same logic
        doGet(req, resp);
    }
}
